procedure ClinicAppointmentReminders {
  about "Remind each patient about their appointment"
  policy ClinicPolicy
  sheet Visits "Visits" { patient: Text, phone: Phone, starts: DateTime, status: Text, copay: Money, diagnosis: Text private }
  trigger every day at 18:00

  let all = fetch Visits
  let due = filter all where date_of(starts) == today() + 3 days and status == "booked"
  for each r in due up to 100 {
    let m = draft sms to r.phone: "Hi {r.patient default 'there'}, a reminder from the clinic: your appointment is in three days at {time_of(r.starts)}."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}

