procedure ClinicNoShowFollowUp {
  about "Follow up with patients marked no-show"
  policy ClinicPolicy
  sheet Visits "Visits" { patient: Text, phone: Phone, starts: DateTime, status: Text, copay: Money, diagnosis: Text private }
  trigger every day at 08:30

  let all = fetch Visits
  let recent = filter all where status == "no-show" and days_between(starts, today()) <= 1 and days_between(starts, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no no-show patients"
  }
  notify owner "No-show patients to follow up: {n}"
  for each r in recent up to 40 {
    let m = draft sms to r.phone: "Hi {r.patient default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
    update r set status = "followed-up"
  }
}

