procedure DentalNoShowFollowUp {
  about "Follow up with patients marked no-show"
  policy DentalPolicy
  sheet Patients "Patients" { name: Text, mobile: Phone, next_visit: DateTime, status: Text, balance: Money, medical_history: Text private }
  trigger every day at 08:00

  let all = fetch Patients
  let recent = filter all where status == "no-show" and days_between(next_visit, today()) <= 3 and days_between(next_visit, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no no-show patients"
  }
  notify owner "No-show patients to follow up: {n}"
  for each r in recent up to 20 {
    let m = draft sms to r.mobile: "Hi {r.name default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
    update r set status = "contacted"
  }
}

