procedure DentalConfirmNewCleaning {
  about "Confirm a new cleaning and add it to the calendar"
  policy DentalPolicy
  sheet Patients "Patients" { name: Text, mobile: Phone, next_visit: DateTime, status: Text, balance: Money, medical_history: Text private }
  calendar Chairs "Chairs"
  trigger when new row r in Patients

  if r.next_visit < now() + 24 hours {
    notify owner "Short-notice cleaning for {r.name} at {r.next_visit}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft sms to r.mobile: "Hi {r.name}, your cleaning with the office is confirmed for {r.next_visit}."
  let ok = request approval of m from owner timeout 12 hours else stop "confirmation not approved"
  send ok
  let ev = book Chairs { title: "{r.name}", at: r.next_visit, length: 90 minutes }
  update r set status = "confirmed"
}

