procedure TutoringMissedFollowUp {
  about "Follow up with students marked missed"
  policy TutoringPolicy
  sheet Students "Students" { student: Text, parent_email: Email, next_session: DateTime, status: Text, balance: Money, learning_notes: Text private }
  trigger every tuesday at 18:00

  let all = fetch Students
  let recent = filter all where status == "missed" and days_between(next_session, today()) <= 2 and days_between(next_session, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no missed students"
  }
  notify owner "Missed students to follow up: {n}"
  for each r in recent up to 30 {
    let m = draft email to r.parent_email subject "Let's find a new time": "Hi {r.student default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
    update r set status = "contacted"
  }
}

