procedure TutoringOutreachCampaign {
  about "On request, contact recent cancelled students"
  policy TutoringPolicy
  sheet Students "Students" { student: Text, parent_email: Email, next_session: DateTime, status: Text, balance: Money, learning_notes: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Students
  let targets = filter all where status == "cancelled" and days_between(next_session, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft email to r.parent_email subject "We'd love to see you": "Hi {r.student}, come back to the center! Use code RETURN20 on your next visit."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

