procedure RestaurantReservationReminders {
  about "Remind each guest about their reservation"
  policy RestaurantPolicy
  sheet Bookings "Bookings" { guest: Text, phone: Phone, at: DateTime, status: Text, deposit: Money, allergies: Text private }
  trigger every day at 08:00

  let all = fetch Bookings
  let due = filter all where date_of(at) == today() + 7 days and status == "booked"
  for each r in due up to 20 {
    let m = draft sms to r.phone: "Hi {r.guest}, a reminder from the restaurant: your reservation is in a week at {time_of(r.at)}."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
    update r set status = "reminded"
  }
}

