procedure RestaurantNoShowFollowUp {
  about "Follow up with guests marked no-show"
  policy RestaurantPolicy
  sheet Bookings "Bookings" { guest: Text, phone: Phone, at: DateTime, status: Text, deposit: Money, allergies: Text private }
  trigger every wednesday at 18:00

  let all = fetch Bookings
  let recent = filter all where status == "no-show" and days_between(at, today()) <= 3 and days_between(at, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no no-show guests"
  }
  notify owner "No-show guests to follow up: {n}"
  for each r in recent up to 30 {
    let m = draft sms to r.phone: "Hi {r.guest}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
    update r set status = "followed-up"
  }
}

