procedure RestaurantWinBack {
  about "Nudge guests whose reservation was long ago"
  policy RestaurantPolicy
  sheet Bookings "Bookings" { guest: Text, phone: Phone, at: DateTime, status: Text, deposit: Money, allergies: Text private }
  trigger every day at 08:00

  let all = fetch Bookings
  let old = filter all where days_between(at, today()) >= 60 and status != "cancelled"
  let oldest = sort old by at first 10
  for each r in oldest up to 10 {
    let m = draft sms to r.phone: "Hi {r.guest default 'there'}, it's been a while! We'd love to see you again at the restaurant."
    let ok = request approval of m from owner timeout 6 hours else skip
