procedure RetailLateBalance {
  about "Remind late customers; escalate very late ones"
  policy RetailPolicy
  sheet Orders "Orders" { customer: Text, email: Email, ordered_on: Date, status: Text, total: Money, card_note: Text private }
  trigger every wednesday at 09:00

  let all = fetch Orders
  let late = filter all where total > $0.00 and days_between(ordered_on, today()) > 3
  for each r in late up to 20 {
    if days_between(r.ordered_on, today()) > 14 {
      notify owner "{r.customer} is very late ({r.total}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.customer default 'there'}, our records show a total of {r.total}. Questions? Just reply."
      let ok = request approval of m from owner timeout 2 hours else skip
      send ok
    }
  }
}

