procedure RetailOutreachCampaign {
  about "On request, contact recent cancelled customers"
  policy RetailPolicy
  sheet Orders "Orders" { customer: Text, email: Email, ordered_on: Date, status: Text, total: Money, card_note: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Orders
  let targets = filter all where status == "cancelled" and days_between(ordered_on, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft email to r.email subject "We'd love to see you": "Hi {r.customer default 'there'}, come back to the shop! Use code RETURN20 on your next visit."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

