procedure SalonWinBack {
  about "Nudge clients whose last visit was long ago"
  policy SalonPolicy
  sheet Clients "Clients" { name: Text, phone: Phone, last_visit: Date, status: Text, tab: Money, color_formula: Text private }
  trigger every day at 08:00

  let all = fetch Clients
  let old = filter all where days_between(last_visit, today()) >= 60 and status != "cancelled"
  let oldest = sort old by last_visit first 20
  for each r in oldest up to 20 {
    let m = draft sms to r.phone: "Hi {r.name}, it's been a while! We'd love to see you again at the salon."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

