procedure SalonOutreachCampaign {
  about "On request, contact recent cancelled clients"
  policy SalonPolicy
  sheet Clients "Clients" { name: Text, phone: Phone, last_visit: Date, status: Text, tab: Money, color_formula: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Clients
  let targets = filter all where status == "cancelled" and days_between(last_visit, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 100 {
    let m = draft sms to r.phone: "Hi {r.name default 'there'}, come back to the salon! Use code WELCOME10 on your next visit."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}

