procedure AutorepairPickupTimeReminders {
  about "Remind each customer about their pickup time"
  policy AutorepairPolicy
  sheet Jobs "Jobs" { owner_name: Text, phone: Phone, promised: DateTime, status: Text, estimate: Money, vin: Text private }
  trigger every day at 08:00

  let all = fetch Jobs
  let due = filter all where date_of(promised) == today() + 3 days and status == "open"
  for each r in due up to 100 {
    let m = draft sms to r.phone: "Hi {r.owner_name default 'there'}, a reminder from the shop: your pickup time is in three days at {time_of(r.promised)}."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
    update r set status = "reminded"
  }
}

