procedure AutorepairOutreachCampaign {
  about "On request, contact recent cancelled customers"
  policy AutorepairPolicy
  sheet Jobs "Jobs" { owner_name: Text, phone: Phone, promised: DateTime, status: Text, estimate: Money, vin: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Jobs
  let targets = filter all where status == "cancelled" and days_between(promised, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft sms to r.phone: "Hi {r.owner_name}, come back to the shop! Use code COMEBACK15 on your next visit."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

