procedure BakeryOutreachCampaign {
  about "On request, contact recent cancelled customers"
  policy BakeryPolicy
  sheet CakeOrders "CakeOrders" { customer: Text, email: Email, pickup: Date, status: Text, price: Money, address: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch CakeOrders
  let targets = filter all where status == "cancelled" and days_between(pickup, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 100 {
    let m = draft email to r.email subject "We'd love to see you": "Hi {r.customer default 'there'}, come back to the bakery! Use code RETURN20 on your next visit."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

