  let oldest = sort old by sent_on first 15
  for each r in oldest up to 15 {
    let m = draft email to r.email subject "We miss you": "Hi {r.customer default 'there'}, it's been a while! We'd love to see you again at the company."
    let ok = request approval of m from owner timeout 1 day else skip
