procedure DaycareWithdrawnFollowUp {
  about "Follow up with familys marked withdrawn"
  policy DaycarePolicy
  sheet Families "Families" { parent: Text, email: Email, due_date: Date, status: Text, balance: Money, health_notes: Text private }
  trigger every thursday at 11:00

  let all = fetch Families
  let recent = filter all where status == "withdrawn" and days_between(due_date, today()) <= 7 and days_between(due_date, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no withdrawn familys"
  }
  notify owner "Withdrawn familys to follow up: {n}"
  for each r in recent up to 30 {
    let m = draft email to r.email subject "Let's find a new time": "Hi {r.parent}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
    update r set status = "followed-up"
  }
}

