procedure DaycareLateBalance {
  about "Remind late familys; escalate very late ones"
  policy DaycarePolicy
  sheet Families "Families" { parent: Text, email: Email, due_date: Date, status: Text, balance: Money, health_notes: Text private }
  trigger every day at 09:00

  let all = fetch Families
  let late = filter all where balance > $0.00 and days_between(due_date, today()) > 7
  for each r in late up to 30 {
    if days_between(r.due_date, today()) > 21 {
      notify owner "{r.parent} is very late ({r.balance}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.parent default 'there'}, our records show a balance of {r.balance}. Questions? Just reply."
      let ok = request approval of m from owner timeout 1 day else skip
      send ok
    }
  }
}

