procedure CleaningSkippedFollowUp {
  about "Follow up with clients marked skipped"
  policy CleaningPolicy
  sheet Cleanings "Cleanings" { client: Text, phone: Phone, scheduled: DateTime, status: Text, fee: Money, door_code: Text private }
  trigger every day at 08:00

  let all = fetch Cleanings
  let recent = filter all where status == "skipped" and days_between(scheduled, today()) <= 3 and days_between(scheduled, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no skipped clients"
  }
  notify owner "Skipped clients to follow up: {n}"
  for each r in recent up to 40 {
    let m = draft sms to r.phone: "Hi {r.client default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
    update r set status = "contacted"
  }
}

