procedure CleaningOutreachCampaign {
  about "On request, contact recent cancelled clients"
  policy CleaningPolicy
  sheet Cleanings "Cleanings" { client: Text, phone: Phone, scheduled: DateTime, status: Text, fee: Money, door_code: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Cleanings
  let targets = filter all where status == "cancelled" and days_between(scheduled, today()) <= days
