procedure MusicMissedFollowUp {
  about "Follow up with students marked missed"
  policy MusicPolicy
  sheet Lessons "Lessons" { student: Text, parent_phone: Phone, lesson_at: DateTime, status: Text, balance: Money, progress_notes: Text private }
  trigger every day at 17:30

  let all = fetch Lessons
  let recent = filter all where status == "missed" and days_between(lesson_at, today()) <= 2 and days_between(lesson_at, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no missed students"
  }
  notify owner "Missed students to follow up: {n}"
  for each r in recent up to 40 {
    let m = draft sms to r.parent_phone: "Hi {r.student default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
    update r set status = "contacted"
  }
}

