procedure MusicOutreachCampaign {
  about "On request, contact recent cancelled students"
  policy MusicPolicy
  sheet Lessons "Lessons" { student: Text, parent_phone: Phone, lesson_at: DateTime, status: Text, balance: Money, progress_notes: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Lessons
  let targets = filter all where status == "cancelled" and days_between(lesson_at, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft sms to r.parent_phone: "Hi {r.student}, come back to the school! Use code COMEBACK15 on your next visit."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}

