procedure BikeshopPickedUpFollowUp {
  about "Follow up with customers marked picked-up"
  policy BikeshopPolicy
  sheet Repairs "Repairs" { customer: Text, phone: Phone, ready_on: Date, status: Text, estimate: Money, lock_code: Text private }
  trigger every day at 08:00

  let all = fetch Repairs
  let recent = filter all where status == "picked-up" and days_between(ready_on, today()) <= 7 and days_between(ready_on, today()) >= 0
