procedure BikeshopOutreachCampaign {
  about "On request, contact recent cancelled customers"
  policy BikeshopPolicy
  sheet Repairs "Repairs" { customer: Text, phone: Phone, ready_on: Date, status: Text, estimate: Money, lock_code: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Repairs
  let targets = filter all where status == "cancelled" and days_between(ready_on, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 100 {
    let m = draft sms to r.phone: "Hi {r.customer default 'there'}, come back to the shop! Use code COMEBACK15 on your next visit."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

