procedure BookstoreCollectedFollowUp {
  about "Follow up with customers marked collected"
  policy BookstorePolicy
  sheet Holds "Holds" { customer: Text, email: Email, held_until: Date, status: Text, prepaid: Money, phone_note: Text private }
  trigger every wednesday at 18:00

  let all = fetch Holds
  let recent = filter all where status == "collected" and days_between(held_until, today()) <= 2 and days_between(held_until, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no collected customers"
  }
  notify owner "Collected customers to follow up: {n}"
  for each r in recent up to 30 {
    let m = draft email to r.email subject "Let's find a new time": "Hi {r.customer}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
    update r set status = "contacted"
  }
}

