procedure BookstoreOutreachCampaign {
  about "On request, contact recent expired customers"
  policy BookstorePolicy
  sheet Holds "Holds" { customer: Text, email: Email, held_until: Date, status: Text, prepaid: Money, phone_note: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Holds
  let targets = filter all where status == "expired" and days_between(held_until, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft email to r.email subject "We'd love to see you": "Hi {r.customer default 'there'}, come back to the store! Use code COMEBACK15 on your next visit."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

