procedure YogaPausedFollowUp {
  about "Follow up with students marked paused"
  policy YogaPolicy
  sheet Passes "Passes" { name: Text, email: Email, expires_on: Date, status: Text, credit: Money, injury_notes: Text private }
  trigger every day at 18:00

  let all = fetch Passes
  let recent = filter all where status == "paused" and days_between(expires_on, today()) <= 2 and days_between(expires_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no paused students"
  }
  notify owner "Paused students to follow up: {n}"
  for each r in recent up to 20 {
    let m = draft email to r.email subject "Let's find a new time": "Hi {r.name default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
    update r set status = "followed-up"
  }
}

