procedure YogaOutreachCampaign {
  about "On request, contact recent expired students"
  policy YogaPolicy
  sheet Passes "Passes" { name: Text, email: Email, expires_on: Date, status: Text, credit: Money, injury_notes: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Passes
  let targets = filter all where status == "expired" and days_between(expires_on, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft email to r.email subject "We'd love to see you": "Hi {r.name}, come back to the studio! Use code RETURN20 on your next visit."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}

