procedure PetgroomerConfirmNewGrooming {
  about "Confirm a new grooming and add it to the calendar"
  policy PetgroomerPolicy
  sheet Grooms "Grooms" { owner: Text, phone: Phone, appointment: DateTime, status: Text, price: Money, behavior_notes: Text private }
  calendar Tables "Tables"
  trigger when new row r in Grooms

  if r.appointment < now() + 2 hours {
    notify owner "Short-notice grooming for {r.owner} at {r.appointment}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft sms to r.phone: "Hi {r.owner}, your grooming with the salon is confirmed for {r.appointment}."
  let ok = request approval of m from owner timeout 6 hours else stop "confirmation not approved"
  send ok
  let ev = book Tables { title: "{r.owner}", at: r.appointment, length: 45 minutes }
  update r set status = "confirmed"
}

