procedure PrintshopCollectedFollowUp {
  about "Follow up with customers marked collected"
  policy PrintshopPolicy
  sheet Jobs "Jobs" { customer: Text, email: Email, due: Date, status: Text, quote: Money, file_link: Text private }
  trigger every wednesday at 11:00

  let all = fetch Jobs
  let recent = filter all where status == "collected" and days_between(due, today()) <= 3 and days_between(due, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no collected customers"
  }
  notify owner "Collected customers to follow up: {n}"
  for each r in recent up to 40 {
    let m = draft email to r.email subject "Let's find a new time": "Hi {r.customer default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
    update r set status = "followed-up"
  }
}

